-- Aprenda se Divertindo · 16 · Edital TRF4 2025 (FCC): trilha TRF4 e 100 questões
-- Matérias comuns a todos os cargos (Pessoas com Deficiência, IA e Inovação, Sustentabilidade) entram em todas as trilhas.
-- Cole tudo no SQL Editor e clique em Run. Pode rodar de novo sem problema.

-- libera a nova trilha trf4 nos registros de partidas
alter table public.partidas drop constraint if exists partidas_trilha_check;
alter table public.partidas add constraint partidas_trilha_check check (trilha in ('geral','pcba','trf4','policial','tribunais','fiscal','administrativa'));
alter table public.partidas_anonimas drop constraint if exists partidas_anonimas_trilha_check;
alter table public.partidas_anonimas add constraint partidas_anonimas_trilha_check check (trilha in ('geral','pcba','trf4','policial','tribunais','fiscal','administrativa'));

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":3139,"materia":"pcd","nivel":1,"enunciado":"Segundo a Lei 13.146/2015, considera-se pessoa com deficiência aquela que tem impedimento:","opcoes":["De longo prazo que, em interação com barreiras, pode obstruir sua participação plena na sociedade","De qualquer duração ou natureza, desde que comprovado por laudo médico particular ou atestado de clínica","Apenas físico, de natureza permanente e irreversível","Temporário que a impeça de trabalhar por mais de 15 dias"],"explicacao":"Art. 2º: impedimento de longo prazo de natureza física, mental, intelectual ou sensorial."},{"id":3140,"materia":"pcd","nivel":2,"enunciado":"Pela Lei Brasileira de Inclusão, a avaliação da deficiência, quando necessária, será:","opcoes":["Biopsicossocial, feita por equipe multiprofissional e interdisciplinar","Exclusivamente médica, feita por perito do INSS","Feita por autodeclaração, sem nenhuma análise","Realizada apenas pelo juiz, em processo de interdição com oitiva obrigatória do Ministério Público"],"explicacao":"Art. 2º, § 1º da Lei 13.146/2015."},{"id":3141,"materia":"pcd","nivel":2,"enunciado":"Na Lei Brasileira de Inclusão, a curatela da pessoa com deficiência:","opcoes":["É medida extraordinária e afeta apenas atos de natureza patrimonial e negocial","Alcança o direito ao voto e ao casamento","É obrigatória para toda pessoa com deficiência intelectual ou mental, desde o primeiro diagnóstico","Tem duração indeterminada e não pode ser revista"],"explicacao":"Arts. 84 e 85: não alcança corpo, sexualidade, matrimônio, privacidade, educação, saúde, trabalho e voto."},{"id":3142,"materia":"pcd","nivel":2,"enunciado":"Na tomada de decisão apoiada, a pessoa com deficiência escolhe:","opcoes":["Pelo menos duas pessoas idôneas, de sua confiança, para apoiá-la","Um curador nomeado pelo Ministério Público","Um único tutor indicado pelo juiz","Um representante legal que decide em seu lugar em todos os atos da vida civil"],"explicacao":"Art. 1.783-A do Código Civil, incluído pela LBI."},{"id":3143,"materia":"pcd","nivel":1,"enunciado":"Na LBI, adaptações razoáveis são modificações e ajustes que:","opcoes":["Não acarretem ônus desproporcional e indevido","Devem ser feitas a qualquer custo","Dependem sempre de lei municipal específica que as autorize","Só valem para prédios públicos novos"],"explicacao":"Art. 3º, VI. Recusar adaptação razoável configura discriminação."},{"id":3144,"materia":"pcd","nivel":1,"enunciado":"Segundo a LBI, a recusa de adaptações razoáveis e de tecnologias assistivas é considerada:","opcoes":["Discriminação em razão da deficiência","Mera irregularidade administrativa","Exercício regular de direito","Infração apenas trabalhista"],"explicacao":"Art. 4º, § 1º da Lei 13.146/2015."},{"id":3145,"materia":"pcd","nivel":1,"enunciado":"O conceito de desenho universal, na Lei 13.146/2015, refere-se a:","opcoes":["Produtos e ambientes concebidos para serem usados por todas as pessoas, sem adaptação","Projetos feitos exclusivamente para pessoas com deficiência física ou com mobilidade reduzida","Padrão internacional de placas de trânsito","Modelo de edifício público com rampa externa"],"explicacao":"Art. 3º, II da LBI."},{"id":3146,"materia":"pcd","nivel":1,"enunciado":"Barreiras atitudinais, segundo a LBI, são:","opcoes":["Atitudes ou comportamentos que impedem a participação social da pessoa com deficiência","Obstáculos em calçadas e vias públicas","Falhas em sites, aplicativos e sistemas de informática que impedem o acesso à informação","Degraus e portas estreitas em edifícios"],"explicacao":"Art. 3º, IV, 'e'."},{"id":3147,"materia":"pcd","nivel":2,"enunciado":"Para a LBI, pessoa com mobilidade reduzida inclui, além de pessoas com deficiência:","opcoes":["Idoso, gestante, lactante, pessoa com criança de colo e obeso","Apenas cadeirantes e pessoas com muletas","Somente idosos com mais de 80 anos","Somente pessoas com deficiência visual"],"explicacao":"Art. 3º, IX da Lei 13.146/2015."},{"id":3148,"materia":"pcd","nivel":2,"enunciado":"Nos estacionamentos abertos ao público, a LBI determina reserva de vagas para pessoa com deficiência de:","opcoes":["2% do total, garantida no mínimo uma vaga","5% do total, sem mínimo garantido","10% das vagas cobertas","Uma vaga a cada 50, apenas em shoppings e supermercados"],"explicacao":"Art. 47. Para idosos, o Estatuto da Pessoa Idosa prevê 5%."},{"id":3149,"materia":"pcd","nivel":2,"enunciado":"Nos programas habitacionais públicos, a LBI reserva para pessoas com deficiência no mínimo:","opcoes":["3% das unidades habitacionais","10% das unidades","1% das unidades","20% das unidades"],"explicacao":"Art. 32, I da Lei 13.146/2015."},{"id":3150,"materia":"pcd","nivel":3,"enunciado":"Segundo a LBI, os hotéis e pousadas devem ter dormitórios acessíveis em proporção de:","opcoes":["10% do total, garantida no mínimo uma unidade","2% do total, sem mínimo","50% dos quartos do térreo","Um quarto por andar, nos hotéis com mais de 5 andares"],"explicacao":"Art. 45, § 1º da Lei 13.146/2015."},{"id":3151,"materia":"pcd","nivel":2,"enunciado":"A Lei 11.126/2005 assegura à pessoa com deficiência visual o direito de:","opcoes":["Ingressar e permanecer com cão-guia em veículos e estabelecimentos de uso coletivo","Receber cão-guia gratuitamente do governo federal, com treinamento custeado pelo SUS","Ter isenção de IPVA em qualquer veículo","Ter prioridade em concursos com cão-guia"],"explicacao":"Vale para ambientes públicos e privados de uso coletivo."},{"id":3152,"materia":"pcd","nivel":2,"enunciado":"A Lei 8.899/1994 concede passe livre no transporte coletivo interestadual às pessoas com deficiência:","opcoes":["Comprovadamente carentes","De qualquer renda, sem comprovação","Apenas maiores de 65 anos","Apenas servidoras públicas"],"explicacao":"Regulamentada pelo Decreto 3.691/2000, que reserva dois assentos por veículo."},{"id":3153,"materia":"pcd","nivel":1,"enunciado":"A Lei 8.160/1991 tornou obrigatória, em locais que possibilitem acesso de pessoas com deficiência auditiva, a colocação do:","opcoes":["Símbolo internacional de surdez","Símbolo internacional de acesso (cadeira de rodas)","Mapa tátil em braile","Aviso sonoro de emergência"],"explicacao":"A lei trata da identificação de pessoas com deficiência auditiva."},{"id":3154,"materia":"pcd","nivel":1,"enunciado":"A Lei 10.048/2000 garante atendimento prioritário, entre outros, a:","opcoes":["Pessoas com deficiência, idosos com 60 anos ou mais, gestantes e lactantes","Somente pessoas com deficiência física comprovada por laudo do INSS e carteira específica","Servidores públicos em serviço","Clientes com conta-salário no banco"],"explicacao":"Também a pessoas com crianças de colo e obesos."},{"id":3155,"materia":"pcd","nivel":2,"enunciado":"Pela Lei 7.853/1989, com redação da LBI, recusar a inscrição de aluno em escola em razão de sua deficiência é crime punido com:","opcoes":["Reclusão de 2 a 5 anos e multa","Detenção de 1 a 6 meses","Apenas multa","Advertência à escola"],"explicacao":"Art. 8º, I da Lei 7.853/1989."},{"id":3156,"materia":"pcd","nivel":2,"enunciado":"A Resolução CNJ 401/2021 trata de:","opcoes":["Acessibilidade e inclusão de pessoas com deficiência nos órgãos do Poder Judiciário","Uso de inteligência artificial generativa e de sistemas automatizados nos tribunais federais","Política de sustentabilidade do Judiciário","Teletrabalho de magistrados"],"explicacao":"Prevê, entre outras medidas, comissões permanentes de acessibilidade e inclusão."},{"id":3157,"materia":"pcd","nivel":1,"enunciado":"A Lei 10.436/2002 reconhece a Libras como meio legal de comunicação, mas estabelece que ela:","opcoes":["Não substitui a modalidade escrita da língua portuguesa","Substitui o português em documentos oficiais","É obrigatória para todos os servidores","Só vale em escolas especiais"],"explicacao":"Art. 4º, parágrafo único."},{"id":3158,"materia":"pcd","nivel":3,"enunciado":"O auxílio-inclusão previsto na LBI é devido à pessoa com deficiência moderada ou grave que:","opcoes":["Recebia o BPC e passa a exercer atividade remunerada","Nunca contribuiu e tem mais de 65 anos","Está em gozo de aposentadoria por invalidez há mais de dois anos","Recebe pensão por morte de servidor"],"explicacao":"Art. 94 da LBI, regulamentado pela Lei 14.176/2021."},{"id":3159,"materia":"pcd","nivel":2,"enunciado":"Pela LBI, a pessoa com deficiência que seja parte em processo judicial tem direito a:","opcoes":["Prioridade na tramitação dos processos e procedimentos","Isenção de todas as custas, sem análise de renda","Juiz exclusivo para o seu caso","Prazo em quádruplo para recorrer"],"explicacao":"Art. 9º, VII da Lei 13.146/2015."},{"id":3160,"materia":"ia","nivel":1,"enunciado":"Inteligência artificial generativa é aquela capaz de:","opcoes":["Criar conteúdos novos, como textos, imagens e áudios, a partir de padrões aprendidos","Apenas armazenar, organizar e buscar arquivos que já existem no computador ou na nuvem","Funcionar somente sem dados de treinamento","Executar apenas cálculos aritméticos simples"],"explicacao":"Exemplos: chatbots de texto e geradores de imagem."},{"id":3161,"materia":"ia","nivel":1,"enunciado":"Um modelo de linguagem de larga escala (LLM) é treinado principalmente para:","opcoes":["Prever e gerar texto a partir de grandes volumes de dados textuais","Controlar a temperatura de servidores","Compactar arquivos de vídeo","Substituir o sistema operacional"],"explicacao":"LLM = Large Language Model."},{"id":3162,"materia":"ia","nivel":1,"enunciado":"Na IA generativa, o termo alucinação descreve:","opcoes":["Respostas falsas ou inventadas apresentadas com aparência de verdade","Falha física no processador","Bloqueio do sistema por senha errada","Excesso de usuários conectados"],"explicacao":"Por isso o resultado precisa de revisão humana."},{"id":3163,"materia":"ia","nivel":2,"enunciado":"Um viés algorítmico em sistemas de IA ocorre quando:","opcoes":["O sistema reproduz ou amplia discriminações presentes nos dados ou no projeto","O computador demora a responder","O modelo é treinado em mais de um idioma e passa a misturar palavras nas respostas","O código-fonte é aberto ao público"],"explicacao":"Daí a exigência de não discriminação no uso de IA."},{"id":3164,"materia":"ia","nivel":2,"enunciado":"Agentes de IA se diferenciam de um simples chatbot porque podem:","opcoes":["Planejar e executar tarefas em várias etapas, usando ferramentas com certa autonomia","Funcionar apenas com comandos de voz","Responder somente perguntas de sim ou não, sem acesso à internet ou a bases externas","Operar sem nenhum modelo de linguagem"],"explicacao":"Agentes combinam modelos com ferramentas e ações."},{"id":3165,"materia":"ia","nivel":2,"enunciado":"Entre os riscos da IA generativa no serviço público, destaca-se:","opcoes":["O compartilhamento indevido de dados sensíveis inseridos nos prompts","A impossibilidade de gerar textos em português","O aumento obrigatório de servidores","A extinção do processo eletrônico"],"explicacao":"Dados pessoais e sigilosos exigem cuidado."},{"id":3166,"materia":"ia","nivel":2,"enunciado":"A Resolução CNJ 332/2020 dispõe sobre:","opcoes":["Ética, transparência e governança na produção e no uso de IA no Poder Judiciário","Acessibilidade e inclusão de pessoas com deficiência nos sistemas eletrônicos dos tribunais","Política ambiental do Judiciário","Gestão de precatórios"],"explicacao":"Primeira norma geral do CNJ sobre IA."},{"id":3167,"materia":"ia","nivel":3,"enunciado":"A Sinapses, mencionada na Resolução CNJ 332/2020, é:","opcoes":["Plataforma do CNJ para armazenar, treinar, distribuir e auditar modelos de IA","Sistema de peticionamento eletrônico do STF usado por advogados e procuradores públicos","Rede social interna dos servidores","Banco nacional de mandados de prisão"],"explicacao":"Solução computacional mantida pelo CNJ."},{"id":3168,"materia":"ia","nivel":3,"enunciado":"Segundo a Resolução CNJ 332/2020, o uso de modelos de IA em matéria penal:","opcoes":["Não deve ser estimulado, sobretudo para soluções preditivas","É obrigatório para dosar a pena","É livre, sem restrições","Só é vedado nos juizados especiais criminais e nas turmas recursais"],"explicacao":"Exceções: automação e cálculos, como de pena e prescrição."},{"id":3169,"materia":"ia","nivel":2,"enunciado":"A Resolução CNJ 395/2021 institui:","opcoes":["A Política de Gestão da Inovação no Poder Judiciário","O Código de Ética da Magistratura","O processo judicial eletrônico","A política de segurança da informação"],"explicacao":"Também trata dos laboratórios de inovação."},{"id":3170,"materia":"ia","nivel":1,"enunciado":"No design thinking, a primeira etapa, voltada a compreender o usuário, é a:","opcoes":["Empatia (imersão)","Prototipação","Teste","Implementação"],"explicacao":"Depois vêm definição, ideação, prototipação e teste."},{"id":3171,"materia":"ia","nivel":1,"enunciado":"A fase do design thinking em que se gera o maior número de ideias possíveis é a:","opcoes":["Ideação","Empatia","Teste","Definição"],"explicacao":"Brainstorming é técnica comum nessa fase."},{"id":3172,"materia":"ia","nivel":2,"enunciado":"Inovação aberta (open innovation) é o modelo em que a organização:","opcoes":["Combina ideias internas com ideias e parcerias externas","Inova apenas com seus próprios servidores","Proíbe qualquer parceria com universidades","Divulga todo o seu código obrigatoriamente"],"explicacao":"Conceito difundido por Henry Chesbrough."},{"id":3173,"materia":"ia","nivel":1,"enunciado":"Um laboratório de inovação em um tribunal tem como objetivo:","opcoes":["Criar e testar soluções novas para problemas do serviço, com foco no usuário","Fazer perícias técnicas em processos","Guardar provas apreendidas","Realizar exames médicos periódicos em servidores, magistrados e estagiários do tribunal"],"explicacao":"Previsto na política de inovação do CNJ."},{"id":3174,"materia":"ia","nivel":2,"enunciado":"Na política de inovação do Judiciário, a rede que integra os laboratórios dos tribunais é a:","opcoes":["RenovaJud","Sinapses","Datajud","SEEU"],"explicacao":"Rede de Inovação do Poder Judiciário Brasileiro."},{"id":3175,"materia":"ia","nivel":2,"enunciado":"O protótipo, no design thinking, serve para:","opcoes":["Testar a ideia de forma rápida e barata antes da solução final","Encerrar o projeto sem consultar o usuário","Substituir a fase de empatia","Registrar a patente da ideia"],"explicacao":"Erros cedo custam menos."},{"id":3176,"materia":"sust","nivel":1,"enunciado":"Desenvolvimento sustentável, segundo o Relatório Brundtland, é aquele que:","opcoes":["Atende às necessidades do presente sem comprometer as das gerações futuras","Prioriza o crescimento econômico acima de tudo, mesmo à custa do meio ambiente","Proíbe o uso de recursos naturais","Vale apenas para países ricos"],"explicacao":"Relatório 'Nosso Futuro Comum', de 1987."},{"id":3177,"materia":"sust","nivel":1,"enunciado":"A Agenda 2030 da ONU reúne:","opcoes":["17 Objetivos de Desenvolvimento Sustentável e 169 metas","8 Objetivos do Milênio","10 metas climáticas obrigatórias, com sanções aos países que as descumprirem","30 objetivos ambientais"],"explicacao":"Adotada em 2015 pelos países membros."},{"id":3178,"materia":"sust","nivel":1,"enunciado":"O ODS 16 da Agenda 2030, ligado diretamente ao Judiciário, trata de:","opcoes":["Paz, justiça e instituições eficazes","Vida na água","Energia limpa e acessível","Fome zero"],"explicacao":"Inclui acesso à justiça para todos."},{"id":3179,"materia":"sust","nivel":2,"enunciado":"O ODS 13 da Agenda 2030 trata de:","opcoes":["Ação contra a mudança global do clima","Igualdade de gênero","Educação de qualidade","Água potável e saneamento"],"explicacao":"Medidas urgentes contra a mudança do clima e seus impactos."},{"id":3180,"materia":"sust","nivel":2,"enunciado":"Na CF/88, a defesa do meio ambiente aparece também como:","opcoes":["Princípio da ordem econômica, com tratamento diferenciado conforme o impacto ambiental","Competência exclusiva dos municípios","Direito apenas dos proprietários rurais","Matéria vedada a emendas constitucionais, por ser cláusula pétrea expressa no art. 60 da CF/88"],"explicacao":"Art. 170, VI da Constituição."},{"id":3181,"materia":"sust","nivel":2,"enunciado":"Na Lei 14.133/2021, o desenvolvimento nacional sustentável é:","opcoes":["Princípio e também objetivo do processo licitatório","Mera recomendação, sem força legal","Aplicável só a obras de saneamento","Critério proibido de desempate"],"explicacao":"Arts. 5º e 11, IV da Lei 14.133/2021."},{"id":3182,"materia":"sust","nivel":2,"enunciado":"Na Lei 14.133/2021, a busca da proposta mais vantajosa deve considerar:","opcoes":["O ciclo de vida do objeto","Apenas o menor preço de compra","Somente o prazo de entrega","A localização do fornecedor"],"explicacao":"Art. 11, I: inclui custos de uso, manutenção e descarte."},{"id":3183,"materia":"sust","nivel":3,"enunciado":"Nos contratos da Lei 14.133/2021, a remuneração variável pode ser vinculada a:","opcoes":["Critérios de sustentabilidade ambiental, entre outros de desempenho","Opinião pessoal do fiscal","Sorteio entre os licitantes","Valor das ações do contratado negociadas na bolsa de valores no mês anterior"],"explicacao":"Art. 144 da Lei 14.133/2021."},{"id":3184,"materia":"sust","nivel":3,"enunciado":"Na Lei 12.187/2009, o compromisso nacional voluntário era reduzir as emissões projetadas até 2020 entre:","opcoes":["36,1% e 38,9%","10% e 15%","50% e 60%","80% e 90%"],"explicacao":"Art. 12 da PNMC."},{"id":3185,"materia":"sust","nivel":2,"enunciado":"A Resolução CNJ 433/2021 institui:","opcoes":["A Política Nacional do Poder Judiciário para o Meio Ambiente","A Política de Acessibilidade e Inclusão do Poder Judiciário brasileiro","As regras de uso de IA nos tribunais","O Código de Ética dos Servidores"],"explicacao":"Trata da atuação ambiental do Judiciário."},{"id":3186,"materia":"sust","nivel":1,"enunciado":"O chamado tripé da sustentabilidade combina as dimensões:","opcoes":["Ambiental, social e econômica","Política, militar e religiosa","Urbana, rural e marítima","Federal, estadual e municipal"],"explicacao":"Também chamado triple bottom line."},{"id":3187,"materia":"port","nivel":1,"enunciado":"Assinale a frase em que o acento indicativo de crase está correto:","opcoes":["O processo foi entregue à juíza substituta.","Ele começou à estudar ontem.","Fiquei frente à frente com o réu.","Vou à pé até o fórum."],"explicacao":"Não há crase antes de verbo, em expressões com palavras repetidas e antes de 'pé'."},{"id":3188,"materia":"port","nivel":2,"enunciado":"Assinale a frase em que o pronome está colocado de acordo com a norma-padrão:","opcoes":["Não se esqueça de protocolar o recurso.","Me disseram que o prazo acabou.","Não esqueça-se do prazo.","Ninguém avisou-me da audiência."],"explicacao":"Palavra negativa atrai o pronome; não se inicia frase com pronome oblíquo."},{"id":3189,"materia":"rl","nivel":1,"enunciado":"Um produto de R$ 200,00 sofre aumento de 10% e depois desconto de 10%. O preço final é:","opcoes":["R$ 198,00","R$ 200,00","R$ 202,00","R$ 180,00"],"explicacao":"200 × 1,1 × 0,9 = 198."},{"id":3190,"materia":"rl","nivel":1,"enunciado":"Se 4 servidores analisam 60 processos em um dia, 6 servidores, no mesmo ritmo, analisam:","opcoes":["90 processos","80 processos","100 processos","120 processos"],"explicacao":"Regra de três direta: 60 × 6 / 4 = 90."},{"id":3191,"materia":"prev","nivel":1,"enunciado":"Pela CF/88, a seguridade social compreende:","opcoes":["Saúde, previdência social e assistência social","Saúde, educação, segurança pública e moradia digna","Previdência, trabalho e moradia","Assistência, cultura e lazer"],"explicacao":"Art. 194 da Constituição."},{"id":3192,"materia":"prev","nivel":1,"enunciado":"Dos ramos da seguridade social, exige contribuição do beneficiário:","opcoes":["A previdência social","A saúde","A assistência social","Nenhum deles"],"explicacao":"Saúde é para todos; assistência, para quem dela necessitar."},{"id":3193,"materia":"prev","nivel":2,"enunciado":"É princípio da seguridade social previsto no art. 194 da CF:","opcoes":["Uniformidade e equivalência dos benefícios às populações urbanas e rurais","Gestão exclusiva pela União, sem participação de trabalhadores e empregadores","Cobrança de contribuição para acesso à saúde","Redutibilidade do valor dos benefícios"],"explicacao":"Também universalidade, seletividade, irredutibilidade e diversidade de financiamento."},{"id":3194,"materia":"prev","nivel":2,"enunciado":"A gestão da seguridade social, pela CF, é quadripartite, com participação de:","opcoes":["Trabalhadores, empregadores, aposentados e Governo","União, estados, DF e municípios","INSS, Receita, Ministério e TCU","Juízes, promotores, defensores públicos e advogados privados"],"explicacao":"Art. 194, parágrafo único, VII."},{"id":3195,"materia":"prev","nivel":2,"enunciado":"Segundo a CF, nenhum benefício da seguridade social poderá ser criado, majorado ou estendido sem:","opcoes":["A correspondente fonte de custeio total","Aprovação em plebiscito","Lei complementar estadual","Autorização do Tribunal de Contas"],"explicacao":"Regra da contrapartida (art. 195, § 5º)."},{"id":3196,"materia":"prev","nivel":1,"enunciado":"O benefício de prestação continuada (BPC) da assistência social garante:","opcoes":["Um salário mínimo mensal à pessoa com deficiência e ao idoso que comprovem não ter meios de se manter","Aposentadoria integral a quem contribuiu por pelo menos 15 anos, independentemente da idade ou da renda familiar","Seguro-desemprego a trabalhadores rurais","Auxílio-doença a servidores públicos"],"explicacao":"Art. 203, V da CF e Lei 8.742/1993."},{"id":3197,"materia":"prev","nivel":2,"enunciado":"Pela Lei 8.742/1993 (LOAS), o idoso tem direito ao BPC a partir de:","opcoes":["65 anos","60 anos","70 anos","62 anos"],"explicacao":"Desde que comprove não ter meios de prover a própria manutenção."},{"id":3198,"materia":"prev","nivel":2,"enunciado":"A idade mínima para filiar-se ao RGPS como segurado facultativo é:","opcoes":["16 anos","14 anos","18 anos","21 anos"],"explicacao":"Aos 14 anos, apenas como aprendiz (empregado)."},{"id":3199,"materia":"prev","nivel":2,"enunciado":"Em regra, a carência para o auxílio por incapacidade temporária é de:","opcoes":["12 contribuições mensais","180 contribuições mensais","10 contribuições mensais","Não há carência"],"explicacao":"Dispensada em acidentes e em algumas doenças graves."},{"id":3200,"materia":"prev","nivel":2,"enunciado":"A carência da aposentadoria por idade no RGPS é de:","opcoes":["180 contribuições mensais","12 contribuições mensais","60 contribuições mensais","240 contribuições mensais"],"explicacao":"Art. 25, II da Lei 8.213/1991."},{"id":3201,"materia":"prev","nivel":2,"enunciado":"Independe de carência, segundo a Lei 8.213/1991, o:","opcoes":["Auxílio-acidente","Aposentadoria por idade","Auxílio-reclusão","Salário-maternidade da contribuinte individual"],"explicacao":"Também pensão por morte e salário-família."},{"id":3202,"materia":"prev","nivel":3,"enunciado":"O auxílio-acidente corresponde a:","opcoes":["50% do salário de benefício, com natureza indenizatória","100% do salário de contribuição, com natureza substitutiva da remuneração","Um salário mínimo fixo","70% do último salário"],"explicacao":"Devido após consolidação de lesões que reduzam a capacidade."},{"id":3203,"materia":"prev","nivel":2,"enunciado":"O salário-maternidade da segurada empregada tem duração de:","opcoes":["120 dias","60 dias","180 dias","90 dias"],"explicacao":"Pago pela empresa, que compensa com as contribuições."},{"id":3204,"materia":"prev","nivel":2,"enunciado":"Após a Lei 13.846/2019, o auxílio-reclusão é devido aos dependentes do segurado de baixa renda recolhido em regime:","opcoes":["Fechado","Aberto","Semiaberto ou aberto","Domiciliar"],"explicacao":"Também passou a exigir carência de 24 contribuições."},{"id":3205,"materia":"prev","nivel":2,"enunciado":"Na Lei 8.213/1991, integram a primeira classe de dependentes:","opcoes":["Cônjuge, companheiro e filho menor de 21 anos ou inválido","Pais e irmãos","Avós e netos","Pais, irmãos e demais parentes até o terceiro grau em linha colateral"],"explicacao":"Para essa classe a dependência econômica é presumida."},{"id":3206,"materia":"prev","nivel":3,"enunciado":"O segurado facultativo mantém a qualidade de segurado, sem contribuir, por até:","opcoes":["6 meses","12 meses","24 meses","3 meses"],"explicacao":"Período de graça do facultativo (art. 15, VI)."},{"id":3207,"materia":"prev","nivel":3,"enunciado":"O direito de revisar o ato de concessão de benefício previdenciário decai em:","opcoes":["10 anos","5 anos","2 anos","20 anos"],"explicacao":"Art. 103 da Lei 8.213/1991. As parcelas prescrevem em 5 anos."},{"id":3208,"materia":"prev","nivel":2,"enunciado":"Pela CF, o regime de previdência complementar é:","opcoes":["Facultativo, autônomo em relação ao RGPS e baseado na constituição de reservas","Obrigatório para todo trabalhador","Administrado exclusivamente pelo INSS e custeado pelas contribuições de empregadores e da União","Sustentado por impostos gerais"],"explicacao":"Art. 202 da Constituição."},{"id":3209,"materia":"prev","nivel":2,"enunciado":"A Lei 12.618/2012 instituiu a previdência complementar dos servidores federais, administrada pelas:","opcoes":["Funpresp-Exe, Funpresp-Leg e Funpresp-Jud","Caixas de assistência mantidas pelos próprios tribunais","Seguradoras privadas abertas","Unidades do INSS"],"explicacao":"Uma fundação para cada Poder."},{"id":3210,"materia":"prev","nivel":3,"enunciado":"Na Lei 12.618/2012, o servidor com remuneração acima do teto do RGPS é inscrito automaticamente no plano e pode cancelar a inscrição em:","opcoes":["90 dias, com devolução das contribuições","30 dias, sem devolução","1 ano, com multa","Qualquer tempo, sem devolução das contribuições"],"explicacao":"Inscrição automática incluída pela Lei 13.183/2015."},{"id":3211,"materia":"prev","nivel":3,"enunciado":"Pela LC 108/2001, a contribuição normal do patrocinador público ao plano de previdência complementar:","opcoes":["Não pode exceder a do participante","Deve ser o dobro da do participante","É livre, sem limite","Só existe se o participante não contribuir"],"explicacao":"Regra da paridade."},{"id":3212,"materia":"prev","nivel":2,"enunciado":"Pela LC 109/2001, as entidades fechadas de previdência complementar são acessíveis:","opcoes":["Só a empregados ou servidores dos patrocinadores e a associados de instituidores","A qualquer pessoa física, mediante contrato com bancos e seguradoras do mercado","Somente a aposentados do INSS","Somente a empresários individuais"],"explicacao":"As abertas são acessíveis a qualquer pessoa."},{"id":3213,"materia":"civ","nivel":2,"enunciado":"Na anticrese, o devedor:","opcoes":["Entrega um imóvel ao credor, que recebe os frutos para compensar a dívida","Entrega um bem móvel em garantia","Oferece seu salário como garantia","Transfere a propriedade do imóvel ao credor até que a dívida seja integralmente paga"],"explicacao":"Art. 1.506 do Código Civil."},{"id":3214,"materia":"civ","nivel":2,"enunciado":"O direito de superfície é concedido:","opcoes":["Por tempo determinado, mediante escritura pública registrada no Cartório de Imóveis","Sempre por prazo indeterminado, podendo ser feito de forma verbal entre as partes envolvidas","Apenas para plantações, nunca para construções","Somente entre parentes"],"explicacao":"Art. 1.369 do Código Civil."},{"id":3215,"materia":"civ","nivel":2,"enunciado":"O usufruto, segundo o Código Civil:","opcoes":["Não pode ser alienado, mas seu exercício pode ser cedido","Pode ser vendido livremente","Transmite-se automaticamente aos herdeiros do usufrutuário","Só recai sobre bens móveis"],"explicacao":"Art. 1.393 do Código Civil."},{"id":3216,"materia":"civ","nivel":2,"enunciado":"O titular do direito real de habitação:","opcoes":["Pode apenas habitar o imóvel com a família, sem alugar nem emprestar","Pode alugar o imóvel a terceiros","Pode vender o imóvel","Pode demolir e reconstruir livremente, desde que avise o proprietário do imóvel"],"explicacao":"Art. 1.414 do Código Civil."},{"id":3217,"materia":"civ","nivel":2,"enunciado":"O mandato em termos gerais só confere poderes de:","opcoes":["Administração","Alienar bens imóveis","Hipotecar e transigir","Doar o patrimônio"],"explicacao":"Para alienar, hipotecar ou transigir exigem-se poderes especiais (art. 661)."},{"id":3218,"materia":"civ","nivel":2,"enunciado":"A transação, segundo o Código Civil:","opcoes":["Interpreta-se restritivamente e só abrange direitos patrimoniais de caráter privado","Pode envolver qualquer direito, inclusive os de família e os direitos da personalidade","Interpreta-se de forma ampliativa","Só é válida se feita em juízo"],"explicacao":"Arts. 841 e 843 do Código Civil."},{"id":3219,"materia":"civ","nivel":3,"enunciado":"No contrato de prestação de serviço, o prazo não pode ser superior a:","opcoes":["4 anos","2 anos","10 anos","1 ano"],"explicacao":"Art. 598 do Código Civil."},{"id":3220,"materia":"pciv","nivel":2,"enunciado":"O IRDR é cabível quando há:","opcoes":["Efetiva repetição de processos sobre a mesma questão de direito e risco à isonomia","Uma única ação com grande repercussão social","Divergência apenas sobre fatos","Pedido de uma das partes para acelerar o julgamento de processo com prioridade legal"],"explicacao":"Art. 976 do CPC."},{"id":3221,"materia":"pciv","nivel":2,"enunciado":"Nos Juizados Especiais Federais, a competência cível abrange causas de até:","opcoes":["60 salários mínimos","40 salários mínimos","20 salários mínimos","100 salários mínimos"],"explicacao":"Lei 10.259/2001. No JEC estadual o teto é 40."},{"id":3222,"materia":"pciv","nivel":3,"enunciado":"Pela Lei 11.419/2006, se o intimando não consultar a intimação eletrônica, ela se considera feita:","opcoes":["Automaticamente, após 10 dias corridos do envio","Nunca, devendo ser repetida por oficial de justiça","Após 30 dias úteis","No mesmo dia do envio"],"explicacao":"Art. 5º, § 3º da Lei do Processo Eletrônico."},{"id":3223,"materia":"trib","nivel":1,"enunciado":"A CBS, criada pela reforma tributária, é de competência:","opcoes":["Da União, substituindo PIS e Cofins","Dos estados, substituindo o ICMS","Dos municípios, substituindo o ISS","Compartilhada entre estados e municípios"],"explicacao":"Regulamentada pela LC 214/2025."},{"id":3224,"materia":"trib","nivel":2,"enunciado":"O Imposto Seletivo (IS) incide sobre:","opcoes":["Bens e serviços prejudiciais à saúde ou ao meio ambiente","Todos os serviços financeiros e operações bancárias do país","Grandes fortunas","Heranças e doações"],"explicacao":"Também chamado 'imposto do pecado'."},{"id":3225,"materia":"trib","nivel":2,"enunciado":"O modelo de IBS e CBS adotado pela reforma tributária é conhecido como:","opcoes":["IVA dual","Imposto único federal","Tributação cumulativa em cascata","Imposto sobre a renda presumida"],"explicacao":"Um tributo federal (CBS) e outro subnacional (IBS)."},{"id":3226,"materia":"trib","nivel":2,"enunciado":"Na reforma tributária, a cobrança do IBS e da CBS segue, em regra, o princípio:","opcoes":["Do destino","Da origem","Da territorialidade da sede","Da anterioridade anual dupla"],"explicacao":"O imposto fica com o local de consumo."},{"id":3227,"materia":"trib","nivel":3,"enunciado":"A reforma tributária prevê a devolução de parte do IBS e da CBS a famílias de baixa renda, mecanismo conhecido como:","opcoes":["Cashback","Drawback","Split payment","Substituição tributária"],"explicacao":"Split payment é o recolhimento no momento do pagamento."},{"id":3228,"materia":"adm","nivel":2,"enunciado":"A Lei 11.416/2006 organiza as carreiras dos servidores do Poder Judiciário da União em:","opcoes":["Analista, Técnico e Auxiliar Judiciário","Escrivão, Oficial e Escrevente","Agente, Assistente e Analista","Técnico, Perito e Delegado"],"explicacao":"Cada carreira tem classes A, B e C."},{"id":3229,"materia":"adm","nivel":2,"enunciado":"Na Lei 14.133/2021, deixaram de existir as modalidades:","opcoes":["Tomada de preços e convite","Pregão e concorrência","Leilão e concurso","Concorrência e diálogo competitivo"],"explicacao":"Modalidades atuais: pregão, concorrência, concurso, leilão e diálogo competitivo."},{"id":3230,"materia":"adm","nivel":2,"enunciado":"Pela Lei 12.846/2013 (Anticorrupção), a pessoa jurídica responde por atos lesivos à Administração de forma:","opcoes":["Objetiva, nas esferas administrativa e civil","Subjetiva, exigindo prova de dolo","Apenas penal","Somente se o dirigente for condenado criminalmente"],"explicacao":"A lei também prevê o acordo de leniência."},{"id":3231,"materia":"adm","nivel":3,"enunciado":"A multa da Lei 12.846/2013 varia de:","opcoes":["0,1% a 20% do faturamento bruto do ano anterior","1% a 5% do lucro líquido","10% a 50% do capital social integralizado da empresa","R$ 1.000 a R$ 10.000"],"explicacao":"Art. 6º, I da Lei Anticorrupção."},{"id":3232,"materia":"const","nivel":2,"enunciado":"O Conselho Nacional de Justiça é composto por:","opcoes":["15 membros, com mandato de 2 anos, admitida uma recondução","11 membros vitalícios","9 ministros do STF","21 membros, com mandato de 4 anos, vedada qualquer recondução"],"explicacao":"Art. 103-B da CF; é presidido pelo presidente do STF."},{"id":3233,"materia":"const","nivel":2,"enunciado":"O Conselho da Justiça Federal funciona junto ao:","opcoes":["STJ, exercendo a supervisão administrativa e orçamentária da Justiça Federal","STF, julgando recursos extraordinários","Ministério da Justiça, como órgão do Poder Executivo federal com função correcional","TCU, como órgão auxiliar"],"explicacao":"Art. 105, parágrafo único, II da CF; suas decisões têm caráter vinculante."},{"id":3234,"materia":"const","nivel":2,"enunciado":"Os juízes dos TRFs são nomeados pelo Presidente da República entre brasileiros com mais de 30 e menos de:","opcoes":["70 anos","65 anos","60 anos","75 anos"],"explicacao":"Limite elevado para 70 anos pela EC 122/2022."},{"id":3235,"materia":"const","nivel":3,"enunciado":"Causas cíveis contra sociedade de economia mista federal, como o Banco do Brasil, são julgadas, em regra, pela:","opcoes":["Justiça estadual","Justiça Federal","Justiça do Trabalho","Justiça Militar"],"explicacao":"Súmula 508 do STF e Súmula 42 do STJ."},{"id":3236,"materia":"gest","nivel":2,"enunciado":"A Estratégia Nacional do Poder Judiciário para 2021-2026 foi instituída pela Resolução CNJ:","opcoes":["325/2020","332/2020","401/2021","433/2021"],"explicacao":"Define missão, visão, valores e macrodesafios do Judiciário."},{"id":3237,"materia":"gest","nivel":2,"enunciado":"A diferença entre governança e governabilidade é que governabilidade se refere:","opcoes":["Às condições políticas e institucionais de legitimidade para governar","À capacidade técnica, financeira e administrativa de executar políticas","Ao controle interno de contas","À gestão de pessoas"],"explicacao":"Governança é a capacidade de ação do Estado na execução."},{"id":3238,"materia":"pen","nivel":3,"enunciado":"A contratação direta ilegal, crime inserido no CP pela Lei 14.133/2021, tem pena de:","opcoes":["Reclusão de 4 a 8 anos e multa","Detenção de 6 meses a 2 anos","Detenção de 3 meses a 1 ano","Reclusão de 1 a 3 anos"],"explicacao":"Art. 337-E do Código Penal."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('prev','pcd','ia','sust') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
